insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('rotating', 'beginner', 'module', 'm01-what-these-engines-size', 1, 'compression.js takes its two power packagings from one module, and pumps.js takes its kilowatt conversion from the same one. Which module?', '["engines/production/gasProperties.js, which already holds the gas constant and the molecular weight of air and is therefore where the shared packagings live.", "engines/facilities/separatorSizing.js, which already supplies the compressibility window and is the nearest shared facilities module.", "lib/units/fieldUnits.js, which both of them read, so one definition of a horsepower serves the liquid machine and the gas machine alike.", "Neither module reads a shared units file. Each one writes its own kilowatt and Btu factors inline at the point of use."]'::jsonb, 2, 'The digest names lib/units/fieldUnits.js as the source of the two power packagings, read by compression.js and by pumps.js.'),
  ('rotating', 'beginner', 'module', 'm01-what-these-engines-size', 2, 'compression.js takes its compressibility validity window from another module. Which one, and what does that tell you about the window?', '["engines/facilities/separatorSizing.js, so the same declared range governs a separator and a compressor stage rather than each module carrying a range of its own.", "engines/production/gasProperties.js, which is also where the Rankine offset and the molecular weight of air come from.", "lib/units/fieldUnits.js, on the grounds that a validity range is a unit-level statement about the correlation.", "It declares its own window internally, which is why the refusal message can quote the limits back at the caller."]'::jsonb, 0, 'The digest preamble lists three sources for compression.js: gasProperties.js for the gas constant, the molecular weight of air and the Rankine offset, separatorSizing.js for the compressibility validity window, and fieldUnits.js for the two power packagings.'),
  ('rotating', 'beginner', 'module', 'm01-what-these-engines-size', 3, 'A caller wraps every call into these two modules in a try block so that no bad input can stop a batch. What has that caller misread about the contract?', '["Only pumps.js returns its refusals, so the try block protects half the chain and leaves the compression half silently unguarded.", "The modules throw on a missing input and return on an out-of-domain one, so a try block catches the first class and misses the second.", "A try block is the documented route, and the mistake is only that the caller must also read the error property afterwards.", "Neither module throws. Every refusal is a returned object carrying an error string, so the try block will never fire and the unchecked result will travel on."]'::jsonb, 3, 'Every refusal in both modules is a returned object carrying an error string. A caller checks a property rather than catching.'),
  ('rotating', 'beginner', 'module', 'm01-what-these-engines-size', 4, 'Why do five of the exports in these modules have nowhere to put an error string at all?', '["They are internal helpers that the modules do not export, so no caller is ever in a position to read an error from them.", "They return a bare number rather than an object, which is the shape a caller of a conversion wants and leaves no room for prose.", "They are pure arithmetic on values another export has already validated, so the guard has been run one level up and the error belongs there.", "They were written before the error convention existed and are kept unchanged so that callers depending on the old shape keep working."]'::jsonb, 1, 'pumps.headFtToPsi, pumps.psiToHeadFt, compression.polytropicExponentRatio, compression.dischargeTempR and compression.actualInletCfm all hand back a single number.'),
  ('rotating', 'beginner', 'module', 'm01-what-these-engines-size', 5, 'State the documented contract those bare-number exports hold instead of an error string.', '["Zero when the inputs cannot be read, on the argument that a zero conversion is visibly useless and cannot be mistaken for a rate.", "The last finite value the export produced, so a caller sweeping a range sees the sequence flatten at the point where the inputs stopped being readable.", "NaN when the inputs cannot be read, never an Infinity and never a plausible number.", "An Infinity when the inputs cannot be read, because it compares as larger than every real figure and therefore fails any bound a caller tests."]'::jsonb, 2, 'Three clauses, and each does work. NaN fails every comparison including one with itself, so a caller who ignores it gets a visibly broken result.'),
  ('rotating', 'beginner', 'module', 'm01-what-these-engines-size', 6, 'What would an Infinity return cost a caller that a NaN return does not?', '["Infinity compares as larger than everything and survives some arithmetic, so it can travel through a bound check looking like a real limit.", "Infinity cannot be serialised into a result object, so a caller showing the return on screen would see an empty field with no way to tell a refusal from a blank.", "Infinity would be rounded to the largest finite double by the print formatting, which turns a refusal into a number that reads as an answer.", "Infinity propagates only through multiplication, so a caller adding it into a running total would lose the refusal entirely."]'::jsonb, 0, 'NaN poisons any arithmetic it touches and fails every comparison. A plausible number would be worse still, because nothing downstream could detect it.'),
  ('rotating', 'beginner', 'module', 'm01-what-these-engines-size', 7, 'A system curve is refused when the friction head is negative and accepted when the static head is negative. What is that pair of guards checking?', '["That the static head is read back off the return and the friction head is not, so only the friction figure is in a position to be validated at all.", "That a negative static head is clipped to zero further down the chain, so the guard has no reason to refuse a value the solve will never see.", "That the two figures enter the coefficient in opposite senses, so a sign error in either one produces the same curve and only one of them needs guarding.", "That friction always takes energy out of the fluid whichever way it flows, while a pump discharging into a vessel below it is an ordinary station with a negative lift."]'::jsonb, 3, 'The message says a static head may be negative but cannot be missing. The friction message asks for a friction head at a stated positive flow.'),
  ('rotating', 'beginner', 'module', 'm01-what-these-engines-size', 8, 'A pump curve built from three readings at one flow is refused although three points were supplied. What does that refusal demonstrate?', '["The count was never the real guard. Two points and three points at one flow reach the same check and share the same message about distinct flows.", "Presence is not sufficiency. The count was met and the fit still had nothing to work with, so the module states the second condition separately.", "A quadratic needs four points rather than three, and the degenerate message is how the module says so without changing the stated minimum.", "Three readings at one flow are refused as a negative-head case, since a repeated flow makes the residual at that flow ambiguous in sign."]'::jsonb, 1, 'The engine returns "the pump curve points are degenerate: give three distinct flows", which is a different message from "a pump curve needs at least three flow and head points".'),
  ('rotating', 'beginner', 'module', 'm01-what-these-engines-size', 9, 'Two different requests both come back as { error: "both a pump curve and a system curve are needed" }. Which pair?', '["A duty asked on a curve that rises with flow, and a duty asked with a search limit below the crossing.", "A system curve given no static head, and a system curve given no flow to state its friction at.", "A duty asked with no system to work into, and a duty asked with no pump.", "A power call made at no flow, and a power call made at no specific gravity."]'::jsonb, 2, 'The duty solve needs both objects and names both in one message, because either one missing leaves it with the same half of the question.'),
  ('rotating', 'beginner', 'module', 'm01-what-these-engines-size', 10, 'What does the pump chain ask AT the solved crossing rather than anywhere else?', '["The shutoff head, the droop flag and the conditioning of the fit, which are the three fields that describe the machine at its duty.", "The friction coefficient the system implies, which cannot be worked out until the flow the station will actually run at is known.", "The best efficiency flow, which the module recovers from the catalogue points once the duty has fixed which part of the curve is in use.", "The power, the suction margin and the operating region, which is why every one of them moves when the system moves."]'::jsonb, 3, 'Catalogue points give a curve, a friction head at a stated flow gives a system curve, the two cross at exactly one flow, and the three follow-on questions are asked there.'),
  ('rotating', 'beginner', 'module', 'm01-what-these-engines-size', 11, 'Which engine module owns what the piping upstream and downstream costs in pressure?', '["engines/facilities/lineHydraulics.js. These two modules size machines and the line loss is a separate question.", "engines/facilities/separatorSizing.js, which already carries the pressure-drop work for the facilities side of the package.", "pumps.js itself, inside the system curve, which is where the friction head at a stated flow is turned into a coefficient.", "engines/production/gasProperties.js, since a line loss on the gas side and a line loss on the liquid side share one correlation."]'::jsonb, 0, 'The system curve takes a friction head as an input. Working out what that friction head is belongs to the line-sizing module.'),
  ('rotating', 'beginner', 'module', 'm01-what-these-engines-size', 12, 'A report says a compressor selection is complete because every returned value was finite and no error string came back. Which failure mode is that report silent about?', '["The discharge temperature, which the package computes but never compares against any limit, so a finite return says nothing about whether it is survivable.", "Surge. There is no surge line, no surge margin, no recycle valve and no anti-surge calculation anywhere in the engines package.", "The gas composition, which the package refuses to accept at all, so a finite return can only ever describe air.", "The stage count, which is reported without the limit that governed it and therefore cannot be checked."]'::jsonb, 1, 'Reading an absence as a pass. A result that says nothing about a failure mode is not a result that clears it.'),
  ('rotating', 'beginner', 'module', 'm01-what-these-engines-size', 13, 'Where do seals and bearings appear anywhere in these two modules?', '["In the brake power, which carries a fixed allowance for seal and bearing drag on top of the hydraulic power.", "In the operating region return, as a separate seal-life field that falls away either side of best efficiency flow.", "Only inside returned prose, in a note saying that bearing and seal life shorten at low flow.", "Nowhere at all. The package never mentions a seal or a bearing in any return or any message."]'::jsonb, 2, 'There is no mechanical seal calculation and no bearing calculation. One sentence of returned prose is the whole of what the package knows about them.'),
  ('rotating', 'beginner', 'module', 'm01-what-these-engines-size', 14, 'Which of these does the package NOT calculate?', '["Wheel selection and rod loading, along with the machine curve and the valve dynamics that sit beside them.", "The head a fitted catalogue curve gives at any stated flow, which requires the vendor curve rather than the four readings.", "The brake power at a solved duty, which needs a motor efficiency the module does not carry.", "The compression ratio a stage works at, which is a frame property and comes off a vendor performance run."]'::jsonb, 0, 'There is no machine curve, no wheel selection, no valve dynamics and no rod loading. A vendor performance run on a specific frame answers those.'),
  ('rotating', 'beginner', 'module', 'm01-what-these-engines-size', 15, 'An engineer fills in a refused input with a reasonable figure and reruns, and every downstream number comes back clean. What is wrong with that result?', '["It will carry a warning string rather than an error string, which the caller is likely to suppress in a report that already shows an answer.", "It will differ from the correct answer only in the last two decimals, which is too small a difference for any check in the chain to detect.", "It will be refused again at the next guard, because the modules revalidate every input at every step of the chain.", "It is internally consistent and built on a number nobody supplied, so the duty, the power and the region are all correct calculations on an invented input."]'::jsonb, 3, 'The message named the input because the input is the fix. The engine has no way to distinguish a supplied figure from a guessed one.'),
  ('rotating', 'beginner', 'module', 'm02-two-curves-and-no-operating-point', 1, 'The OKONO catalogue reads 540.000000 ft at zero flow and the fit returns a shutoff head of 540.203016 ft. What is that gap?', '["A rounding introduced when the engine normalises the flow by the scale.", "The fit sitting closest to all four readings at once rather than passing through any one of them.", "The catalogue reading being a measured point and the fitted value being that same point corrected for the conditioning of the solve.", "The quadratic being extrapolated below the lowest flow it was given, since a shutoff reading sits outside the range the other three points cover."]'::jsonb, 1, 'A quadratic has three coefficients and there are four points, so no quadratic hits all four. The difference is 0.203016 ft and every one of the four residuals is non-zero.'),
  ('rotating', 'beginner', 'module', 'm02-two-curves-and-no-operating-point', 2, 'Why is the OKONO fit written in the variable q over the scale rather than in raw gallons per minute?', '["It makes the shutoff head fall out as c0, which a fit in raw flow could not deliver without a separate evaluation at zero.", "It lets one fitted curve be reused on a pump of a different size by rescaling, since the normalised curve is dimensionless.", "It removes the need for the least-squares step, because three normalised points determine a quadratic exactly.", "It keeps the three coefficients within a few orders of magnitude of each other, which is what the arithmetic behind the fit is sensitive to."]'::jsonb, 3, 'The scale is the largest flow in the point set, 1900.000000 gpm here. Raw flows to nineteen hundred have squares running to several million, spread over many orders of magnitude before the normal equations square anything.'),
  ('rotating', 'beginner', 'module', 'm02-two-curves-and-no-operating-point', 3, 'Which figure does the OKONO fit report as its shutoff head, and where does it come from?', '["540.203016 ft, which is c0, the fitted head at zero flow.", "540.000000 ft, which is the first catalogue reading, copied through because a shutoff is a measurement rather than a fitted quantity.", "0.738126 ft, which is c1, the linear coefficient.", "291.101770 ft, which is the magnitude of c2 and the head the curve loses across the full normalised range."]'::jsonb, 0, 'The shutoff head is simply the fitted head at zero flow. Every term in q over the scale vanishes there and c0 is what is left.'),
  ('rotating', 'beginner', 'module', 'm02-two-curves-and-no-operating-point', 4, 'An R squared of 0.999985896 comes back on the OKONO fit. What exactly is that the share of?', '["The catalogue range over which the fitted curve stays inside its own conditioning bound.", "The four residuals expressed against the largest head in the point set, summed and subtracted from one.", "The variance in the readings that the fitted curve explains.", "The flows where the fit and the catalogue agree."]'::jsonb, 2, 'A value near one means the points sit close to the curve. That is the entire claim it makes.'),
  ('rotating', 'beginner', 'module', 'm02-two-curves-and-no-operating-point', 5, 'A point set whose head climbs with flow is fitted and comes back with an R squared of 1.000000000. What has that perfect score failed to notice?', '["That the conditioning of the solve was worse than on any drooping set in this course, which is where a rising point set actually shows itself.", "That the fitted c2 came back as zero, so the quadratic collapsed to a straight line through the three readings.", "That only three readings were supplied, which is below the minimum the fit refuses under.", "That the curve is the wrong shape to be a centrifugal head curve, which the same return says in a droops flag of false and in prose."]'::jsonb, 3, 'Three points and three coefficients leave nothing for the curve to miss, so the score is perfect. R squared grades the fit against the points and nothing more.'),
  ('rotating', 'beginner', 'module', 'm02-two-curves-and-no-operating-point', 6, 'Three readings that all carry the same head are fitted. What does the engine return for R squared, and why?', '["1.000000000, because a horizontal line passes exactly through three points that all sit at the same height.", "Null, because the total sum of squares is zero and the share of a variance that does not exist is undefined.", "0.000000, because a flat curve explains none of the behaviour the readings were taken to capture.", "The same value as the previous fit, because the engine carries the last finite score forward when the current one cannot be formed."]'::jsonb, 1, 'The engine could have returned 1 or 0 and either would be a number where there is no number. Null is what nothing to explain looks like in a return.'),
  ('rotating', 'beginner', 'module', 'm02-two-curves-and-no-operating-point', 7, 'What does the condition number of the normal-equation matrix answer that R squared does not?', '["Whether the point set contains enough distinct flows for a quadratic, which R squared cannot see because it is formed after the solve.", "How far the fitted shutoff sits from the first catalogue reading, expressed as a bound rather than as a residual.", "Whether the linear system behind the curve could be solved at all, which is a separate question from how well the curve describes the points.", "Whether the fitted curve falls with flow, which is the property the duty solve further down the module requires."]'::jsonb, 2, 'A fit can score well on one and badly on the other. The engine reports both because they are two different questions about the same call.'),
  ('rotating', 'beginner', 'module', 'm02-two-curves-and-no-operating-point', 8, 'Across the seven point sets this course fits successfully, what range does the reported condition number take?', '["304.750000 to 366.680892, and the OKONO figure of 334.938111 sits inside it.", "308.014664 to 360.837617, taken from the rising set at the low end and from the last published curve golden at the high end.", "0.999754151 to 1.000000000, the same scale as the fit quality.", "There is no range. OKONO alone carries one."]'::jsonb, 0, 'The smallest and the largest of the seven reported figures. A few hundred is simply what this kind of fit costs.'),
  ('rotating', 'beginner', 'module', 'm02-two-curves-and-no-operating-point', 9, 'Which step in the solve is responsible for the condition number being a few hundred rather than a few tens?', '["Normalising the flow by the scale, which compresses the matrix entries and multiplies the ratio between the largest and smallest of them.", "Forming the normal equations, which squares the condition number of the design matrix underneath them.", "The partial pivoting, which reorders the rows and inflates the 1-norm.", "Evaluating the fitted curve back at each catalogue flow, which accumulates the four residuals into the reported figure."]'::jsonb, 1, 'That squaring is the price of solving a least-squares problem this way, and the engine pays it in the normalised variable rather than in raw gpm.'),
  ('rotating', 'beginner', 'module', 'm02-two-curves-and-no-operating-point', 10, 'What does a condition number of this size cost the fitted coefficients?', '["Nothing measurable. A figure in the hundreds sits far inside the range where double precision is exact and the report is kept for completeness.", "The whole of the fractional part, which is why the coefficients are reported as the engine returns them rather than rounded.", "One digit for each point beyond the three a quadratic needs, so a four-point catalogue costs exactly one.", "Two or three of the sixteen decimal digits double precision carries, which is why they are quoted to six decimals."]'::jsonb, 3, 'It is also why the figure is reported rather than hidden. A reader who knows the fit cost three digits knows not to argue about the fourth.'),
  ('rotating', 'beginner', 'module', 'm02-two-curves-and-no-operating-point', 11, 'The rising point set fits at a condition number of 308.014664 and the three-identical-heads set at 304.750000. What does that pair show?', '["That an unusable point set always conditions better than a usable one, so a low figure is itself a warning worth reading.", "That the two figures are close because both sets carry three points, and the conditioning is determined by the point count alone.", "That conditioning is a statement about the arithmetic and is untroubled by two point sets that are both unusable as pump curves.", "That the engine suppresses the conditioning report when the droops flag is false and substitutes the nearest valid figure."]'::jsonb, 2, 'Neither of those point sets is a usable pump curve. Usability is a statement about the physics and the droops column is where that one is answered.'),
  ('rotating', 'beginner', 'module', 'm02-two-curves-and-no-operating-point', 12, 'Fit the rising set and the engine returns c2 = 94.577778. What does the sign of that coefficient say?', '["The parabola opens upward and the head climbs away with flow, so nothing about the curve describes a centrifugal machine.", "The rows were reordered by the pivoting, which flips the sign of the quadratic term.", "The curve falls more steeply than OKONO, whose c2 of -291.101770 is smaller in magnitude.", "The coefficient is expressed in raw gpm rather than in the normalised variable."]'::jsonb, 0, 'A drooping curve has a negative c2 and OKONO''s is -291.101770. This one is positive.'),
  ('rotating', 'beginner', 'module', 'm02-two-curves-and-no-operating-point', 13, 'The engine reports a rising curve in prose and again in a boolean. Why does it do both rather than either one?', '["The string is for the studio and the boolean for the gate suite, so the two audiences never read the same field and neither can be dropped.", "A string can carry advice and cannot be tested, and a boolean can be tested and cannot explain itself.", "The boolean is formed from the sign of c2 and the string from the residuals, so the two are independent findings that happen to agree here.", "The string is emitted only when the caller asks for it, so the boolean is the field that is always present and the string is the optional half."]'::jsonb, 1, 'Writing one without the other leaves either a machine that cannot act on the finding or a human who cannot understand it.'),
  ('rotating', 'beginner', 'module', 'm02-two-curves-and-no-operating-point', 14, 'Which function further down the module reads the droops flag, and what does it do with it?', '["The power call, which declines to convert a head off a curve that does not fall.", "The operating region check, which cannot judge a curve of the wrong shape.", "The fit itself, which re-solves with the points reordered.", "The duty solve, which refuses to return a crossing for a curve the flag has already disowned."]'::jsonb, 3, 'The fit does not refuse the rising points, because fitting them is a well defined operation and it succeeded. It records what it found and hands the decision on.'),
  ('rotating', 'beginner', 'module', 'm02-two-curves-and-no-operating-point', 15, 'The OKONO system is stated as a static head of 210.000000 ft and a friction head of 165.000000 ft at 1100.000000 gpm. Why is it stated that way?', '["The engine cannot form a coefficient from a single pair, so the flow is supplied as a second independent reading of the same curve.", "Stating a coefficient directly would leave the static head with no flow to be read back at, and the return prints it at the stated flow.", "A friction head at a stated flow is something an engineer measures, and the coefficient it implies is not.", "The two heads have to be given at the same flow so that the solve can subtract them before the crossing is searched for."]'::jsonb, 2, 'The engine takes the measurable pair and works out the coefficient it implies, which here is k = 0.000136363636 ft per gpm squared.'),
  ('rotating', 'beginner', 'module', 'm03-the-duty-point-solved', 1, 'Read down the pump-less-system column of the OKONO table and it runs 330.203016, 310.789450, 252.315660, 154.781645, 18.187407, -157.467056, -372.181743. What does that sequence establish before anything is solved?', '["That the crossing lies between 1200.000000 gpm and 1500.000000 gpm, because the column changes sign exactly once in that interval.", "That the crossing lies below 1200.000000 gpm, since the column has already fallen to within twenty feet of zero by that flow.", "That the two curves are parallel over the upper half of the range, since the column falls by a steady amount on each of the last three rows.", "That there are two crossings in the range, one either side of 900.000000 gpm, because the column changes by more between rows there than anywhere else."]'::jsonb, 0, 'It starts positive and ends negative. The flow where it is zero is the duty point, and 18.187407 ft at 1200.000000 gpm with -157.467056 ft at 1500.000000 gpm brackets it.'),
  ('rotating', 'beginner', 'module', 'm03-the-duty-point-solved', 2, 'At the solved OKONO duty the pump makes 417.801018 ft and the system demands 417.801018 ft. What is the difference between them?', '["0.203016 ft, the same gap the fit carries at the shutoff reading.", "18.187407 ft, the head difference read off the row nearest the crossing.", "2.2737367544323206e-13 ft, the width the search finished on expressed in feet.", "0 ft, which is what solved means here."]'::jsonb, 3, 'Both figures come off the engine, the second read back off the return. The duty is the one flow at which both descriptions hold at once.'),
  ('rotating', 'beginner', 'module', 'm03-the-duty-point-solved', 3, 'Why can the engine go looking for a single answer rather than a set of them?', '["A quadratic and a quadratic cross at two flows at most, and the module discards whichever root falls outside the published catalogue range.", "The pump head falls away from shutoff while the system head climbs from static, so their difference changes sign exactly once.", "The bisection is capped at 200 halvings, so it returns the first crossing it meets and never has the budget to look for a second.", "The system curve is linear in flow and a line crosses a parabola once, which is the property the solve is built on."]'::jsonb, 1, 'One sign change is all a bisection needs. That shape is also why a system demanding more head at zero flow than the pump makes at shutoff has nothing to find.'),
  ('rotating', 'beginner', 'module', 'm03-the-duty-point-solved', 4, 'What are the four pieces of evidence the OKONO duty return carries about the search that produced it?', '["The starting bracket, the number of sign changes seen, the largest step taken and the final midpoint.", "The condition number of the solve, the residual, the iteration cap and the warning string.", "The halvings taken, the bracket it stopped on, the head difference at the flow it returned, and a convergence flag.", "The pump head, the system head, their difference and the flow the difference was evaluated at."]'::jsonb, 2, '55 halvings out of a cap of 200, a bracket of 2.2737367544323206e-13 gpm, a head difference of 0 ft, and converged true with a warning of null.'),
  ('rotating', 'beginner', 'module', 'm03-the-duty-point-solved', 5, 'A colleague proposes building the convergence flag from the bracket width alone. What is wrong with that?', '["On a bracketed sign change bisection always collapses, so the flag could never come back false and would validate nothing.", "The bracket is reported in gallons per minute, so a flag built from it would pass or fail differently on a station stated in cubic metres.", "The bracket halves only when the sign changes, so a search that never sees a sign change would leave the flag undefined rather than false.", "The bracket is smaller than the resolution of the flow itself."]'::jsonb, 0, 'The bracket halves every iteration whatever the function is doing inside it, so a width of nothing is guaranteed rather than earned.'),
  ('rotating', 'beginner', 'module', 'm03-the-duty-point-solved', 6, 'Which input makes the OKONO convergence flag come back false?', '["A system curve whose static head exceeds the pump shutoff head, which leaves the search with no sign change to bracket.", "A search limit set below the crossing, which stops the halvings before the midpoint has settled.", "A point set that rises with flow, whose crossing the solve reports with the flag cleared.", "A curve that returns a non-finite head over part of the range, which sends the comparison false at every step there."]'::jsonb, 3, 'The search is told at every step inside that region that the sign went the same way, so it marches quietly to the bottom of it. The other three come back as refusals rather than as an unconverged answer.'),
  ('rotating', 'beginner', 'module', 'm03-the-duty-point-solved', 7, 'The negative control returns 900.000000 gpm on curves that really cross at 1234.452969 gpm. How far off is that, and which half of the flag caught it?', '["334.938111 gpm off, caught by the bracket, which finished far wider than it does on a healthy solve.", "334.452969 gpm off, caught by the halving count, which ran to 56 against the 55 a healthy solve takes.", "334.452969 gpm off, caught by the residual, which asked whether the curves agree at the flow being returned.", "154.781645 gpm off, caught by the warning string, which the return carries alongside the flag."]'::jsonb, 2, 'The bracket finished at 1.1368683772161603e-13 gpm, which is at the resolution of the numbers themselves, so the bracket half would have called it converged.'),
  ('rotating', 'beginner', 'module', 'm03-the-duty-point-solved', 8, 'What is the residual at the flow the negative control returns?', '["0 ft, the same as on the healthy solve, which is why the bracket had to be consulted instead.", "154.7816454151096 ft.", "334.452969 ft, which is the same figure as the flow error because the two curves cross at unit slope.", "1.1368683772161603e-13 ft, at the resolution of the numbers themselves."]'::jsonb, 1, 'Not a small disagreement in feet of head by any standard this course has used. That is a check which can fail sitting beside one that cannot.'),
  ('rotating', 'beginner', 'module', 'm03-the-duty-point-solved', 9, 'The engine did not throw and did not refuse on the negative control. Why is a flow, a head and a cleared flag the right shape for that failure?', '["The caller may want to see how far off the search went, and every field prints normally so the flag is the one that carries the verdict.", "A throw would have been caught by the studio and turned into a blank panel, which hides a result the reader is entitled to inspect.", "A refusal object carries no numbers, and the module guarantees that every return carries the flow it was asked for.", "The search did converge in the sense the module defines, so a refusal would have contradicted the bracket the return reports."]'::jsonb, 0, 'The one field that says the number is wrong is the one field a hurried caller skips, which is the mistake the lesson names.'),
  ('rotating', 'beginner', 'module', 'm03-the-duty-point-solved', 10, 'A blind loop taking a fixed 200 halvings with no stopping test is run on the same pair of curves. What does it return?', '["A flow 334.452969 gpm away, as the non-finite curve gives.", "A flow it cannot report, because with no stopping test the bracket underflows and the midpoint is no longer representable.", "A flow differing in the sixth decimal, which is the accuracy the stopping test buys back.", "1234.452969 gpm, a difference of 0 gpm from what the engine gives."]'::jsonb, 3, 'Nothing moved when the report was added. The loop breaks exactly where the blind one was already standing still, so the reporting costs no accuracy and buys a flag, a bracket and a residual.'),
  ('rotating', 'beginner', 'module', 'm03-the-duty-point-solved', 11, 'Raise the OKONO station static head to 700.000000 ft and ask for the duty. What comes back, and what evidence travels with it?', '["A duty at the lowest flow in the search window, carrying a cleared convergence flag and a residual of 159.796984 ft of head to go with it.", "A refusal saying the curves do not cross below the search limit, with the limit quoted back.", "A refusal saying this pump cannot start this system, with a shutoff head of 540.203016 ft against a static head of 700.000000 ft.", "A duty of 804.694816 gpm, since a higher static head moves the crossing left along the pump curve."]'::jsonb, 2, 'The gap is 159.796984 ft. Read the evidence and you know both that the selection fails and by how much.'),
  ('rotating', 'beginner', 'module', 'm03-the-duty-point-solved', 12, '"the curves do not cross below 200 gpm: raise the search limit or check the system curve". How does this refusal differ in kind from the other two?', '["It is a warning rather than an error, so the return also carries the flow the search reached before stopping.", "It is a statement about how the question was asked rather than about the machine or the station.", "It names two possible causes rather than one, which is what makes it the only refusal in the module that cannot be acted on directly.", "It is raised by the fit rather than by the duty solve, so it arrives before either curve has been evaluated."]'::jsonb, 1, 'Nothing is wrong with the pump and nothing is wrong with the station. A caller that treats all refusals alike will go looking for a bigger pump when the fix was a search limit.'),
  ('rotating', 'beginner', 'module', 'm03-the-duty-point-solved', 13, 'Hold the OKONO machine and its friction statement and move only the static head. What does the duty do?', '["It moves along the pump curve: 1488.478813 gpm at a static head of 60.000000 ft and 804.694816 gpm at 400.000000 ft.", "It holds the flow it had and raises the head to match, since the machine is unchanged and only the lift above it has moved.", "It falls in head and rises in flow, because a higher lift leaves less of the pump head available for friction to absorb.", "It stays where it was until the static head passes the shutoff head, at which point the solve refuses."]'::jsonb, 0, 'Every duty on that table came out of the same four catalogue readings. What moved was the thing the pump was connected to.'),
  ('rotating', 'beginner', 'module', 'm03-the-duty-point-solved', 14, 'A second station takes the same machine at a static head of 60.000000 ft with a friction head of 380.000000 ft at 1100.000000 gpm. What is the duty and how does the head split?', '["1488.478813 gpm at 362.123069 ft, with 60.000000 ft of that as friction.", "1234.452969 gpm at 417.801018 ft, as on the OKONO station.", "1103.518695 gpm at 442.434987 ft, with 380.000000 ft of it static.", "1103.518695 gpm at 442.434987 ft, of which 60.000000 ft is static and 382.434987 ft is friction."]'::jsonb, 3, 'Its implied coefficient is k = 0.000314049587 ft per gpm squared, against 0.000136363636 on the OKONO station, so this is a far more restrictive piece of piping.'),
  ('rotating', 'beginner', 'module', 'm03-the-duty-point-solved', 15, 'What claim is being made when a datasheet quotes the OKONO pump at 1234.452969 gpm with no station named?', '["That the figure is the pump''s rated flow, which is a property of the catalogue and travels with the machine.", "That the figure came off a converged solve, which is the only claim a duty flow ever carries.", "None that survives. The same machine gives 804.694816 gpm into one station and 1103.518695 gpm into another.", "That the figure is the flow at which the fitted curve and the catalogue readings agree most closely."]'::jsonb, 2, 'A duty point is a property of a pump and a station together. Change the piping, the static head or the friction and it moves, which is why a catalogue can never print it.'),
  ('rotating', 'beginner', 'module', 'm04-power-head-and-pressure', 1, 'At the OKONO duty of 1234.452969 gpm and 417.801018 ft on a fluid of gravity 1.040000, through a pump of efficiency 0.740000 and a motor of 0.920000, what are the three powers?', '["Hydraulic 183.041884 hp, brake 198.958569 hp, motor input 148.363379 hp.", "Hydraulic 135.450994 hp, brake 183.041884 hp and motor input 198.958569 hp.", "Hydraulic 135.450994 hp, brake 198.958569 hp, motor 183.041884 hp.", "Hydraulic 148.363379 hp, brake 183.041884 hp, motor 135.450994 hp."]'::jsonb, 1, 'The motor input is also reported as 148.363379 kW. Each of the three is larger than the one before it because each takes in another set of losses.'),
  ('rotating', 'beginner', 'module', 'm04-power-head-and-pressure', 2, 'Which of the three powers describes the duty rather than the equipment?', '["Brake power, since the shaft is the one place where the duty and the machine meet and a single figure describes both.", "Motor input, since it is the only one a station meter can measure.", "All three equally, because each is asked at the solved duty.", "Hydraulic power, which is this rate lifted this head at this density."]'::jsonb, 3, 'Brake power is what the pump shaft has to be turned with and motor input is what the supply has to deliver. Both of those are statements about the equipment.'),
  ('rotating', 'beginner', 'module', 'm04-power-head-and-pressure', 3, 'How much does the pump lose and how much does the motor lose at the OKONO duty?', '["The pump loses 15.916686 hp and the motor a further 47.590890 hp, the larger share going to the electrical side.", "Neither loses anything. The efficiencies are stated at the duty.", "The pump loses 47.590890 hp and the motor a further 15.916686 hp.", "The motor loses 47.590890 hp and the pump nothing."]'::jsonb, 2, 'Derived from the three powers. Two efficiencies applied in series, each taking its share.'),
  ('rotating', 'beginner', 'module', 'm04-power-head-and-pressure', 4, 'What is lost by multiplying the pump efficiency and the motor efficiency together and applying the product once?', '["The shaft figure, which is the one the coupling, the shaft and the bearings have to survive.", "The supply figure, since a single combined efficiency reaches the hydraulic power and stops there.", "Nothing at all. The product reaches the same supply figure and the shaft figure follows from it by division.", "The hydraulic figure, which can no longer be recovered."]'::jsonb, 0, 'Applying the product once reaches the same supply figure and produces no shaft figure at all.'),
  ('rotating', 'beginner', 'module', 'm04-power-head-and-pressure', 5, 'The OKONO electrical load list is built on 183.041884 hp. What is wrong with that?', '["Nothing. That is the motor input, which is the figure a load list is built on.", "That is the hydraulic power, so the list omits the losses of both the pump and the motor.", "That is the brake power, which is what the shaft receives. The supply has to carry the motor''s own losses on top, a further 15.916686 hp here.", "That is the motor input of 198.958569 hp expressed in kilowatts and read back as horsepower."]'::jsonb, 2, 'Brake power is the right figure to select the motor against, because a motor is rated on what its shaft delivers. It is the wrong figure for the cable, the starter and the running cost, which all carry the supply figure of 198.958569 hp.'),
  ('rotating', 'beginner', 'module', 'm04-power-head-and-pressure', 6, 'The OKONO duty head of 417.801018 ft is converted to a discharge pressure and then converted back. What comes back?', '["Slightly less, the round trip losing the 0.203016 ft the fit carries at shutoff.", "A refusal, because the reverse conversion is one of the bare-number exports and cannot be called on a figure it produced.", "188.100891 ft, since the reverse conversion returns the pressure expressed in the units of head.", "417.801018 ft, because one packaging is used in both directions."]'::jsonb, 3, 'The two directions are separate exports and either could have been written with a different constant inside it. They were not.'),
  ('rotating', 'beginner', 'module', 'm04-power-head-and-pressure', 7, 'Hold the head at 417.801018 ft and change only the fluid. What does the discharge pressure do across gravities of 0.620000 and 1.250000?', '["It runs from 112.137070 psi to 226.082802 psi while the head column never moves.", "It stays at 188.100891 psi, because the head was solved on a curve already stated for the fluid in service.", "It runs from 226.082802 psi to 112.137070 psi, the lighter fluid standing higher in the same machine.", "It runs from 180.866242 psi to 153.736305 psi."]'::jsonb, 0, 'The impeller is doing the same work on every row. What each fluid weighs is what turns that height into a pressure.'),
  ('rotating', 'beginner', 'module', 'm04-power-head-and-pressure', 8, 'Why is a pump curve published in feet of head?', '["Feet are the unit the least-squares fit is conditioned in, so a curve published in psi would have to be refitted before it could be solved against a system.", "A curve in psi cannot be crossed with a system curve, because the system side is stated as a static lift and a friction head and those are both heights.", "A curve in feet is a property of the machine, so one catalogue serves every fluid the machine will ever move.", "The catalogue is measured on water, and only feet carries across unchanged."]'::jsonb, 2, 'A curve in psi would be a property of the machine and one fluid together, and it would have to be reissued for every service.'),
  ('rotating', 'beginner', 'module', 'm04-power-head-and-pressure', 9, 'A vendor quotes a pump at 188.100891 psi on a produced water of gravity 1.040000. What does that machine give on a light condensate of gravity 0.620000?', '["188.100891 psi, since a discharge pressure is what the machine delivers and the fluid only sets the flow.", "112.137070 psi, and nothing about the machine has changed.", "226.082802 psi, because a lighter fluid meets less resistance and the same impeller raises it further.", "The quote cannot be converted. A pressure taken on one fluid carries no information about the same machine on another."]'::jsonb, 1, 'The number that travels between services is the head. The pressure belongs to the machine, the station and the fluid together.'),
  ('rotating', 'beginner', 'module', 'm04-power-head-and-pressure', 10, 'pumps.js exports no constants and names almost none internally. How does this course state what is inside it?', '["By reading the numeric literals out of the module source, which is the only place an inline packaging is written down.", "By quoting the handbook figures the packagings approximate, since a packaging with no name has no other definition available.", "By taking them from the published golden cases, whose own oracle states every constant it was written through.", "By measuring each packaging, choosing inputs that make every other term equal to one and reading it off the return."]'::jsonb, 3, 'Four come out that way: the feet per psi, the horsepower packaging, the kilowatts per horsepower and the default motor efficiency.'),
  ('rotating', 'beginner', 'module', 'm04-power-head-and-pressure', 11, 'Which single call measures the field horsepower packaging, and what does it return?', '["The brake power over the hydraulic power at unit efficiency, which gives 3960.000000.", "The discharge pressure at unit head and unit gravity, inverted, which gives 2.310000000.", "One over the hydraulic power at unit flow, unit head, unit gravity and unit efficiency, which gives 3960.000000.", "The motor input in kilowatts over the motor input in horsepower at unit motor efficiency, which gives 0.745699871582."]'::jsonb, 2, 'Make every other term one and the packaging is the only thing left in the expression.'),
  ('rotating', 'beginner', 'module', 'm04-power-head-and-pressure', 12, 'What is 0.940000000000 in this module, and how was it obtained?', '["The motor efficiency the engine assumes when the caller states none, read as the brake power over the motor input with the argument left out.", "The pump efficiency floor, below which the power call refuses rather than returning a figure.", "The share of the motor input that reaches the shaft on the OKONO station, where 0.920000 was stated.", "The largest motor efficiency the guard will accept, measured by walking the argument upward until it refuses."]'::jsonb, 0, 'A default produces a complete answer with nothing on screen to say it was assumed, which is why it is worth a measurement of its own.'),
  ('rotating', 'beginner', 'module', 'm04-power-head-and-pressure', 13, 'Why is a default worth measuring at all?', '["It is the only value in the module that can change between engine versions, so measuring it dates the answer.", "It produces a complete answer with nothing on screen to say it was assumed, so it cannot be seen any other way.", "It is applied after the guards rather than before them, so a stated value and a defaulted value take different routes.", "It is the one figure the return prints twice, once as supplied and once as used, so the two can be compared."]'::jsonb, 1, 'A reader who states the efficiency has made a decision. A reader who omits it has also made a decision and may not know it.'),
  ('rotating', 'beginner', 'module', 'm04-power-head-and-pressure', 14, 'The feet-per-psi packaging and the horsepower packaging are each unpicked for the water density they carry. What comes out?', '["62.337662337662 lb per ft3 from the first and a figure 0.999553114 of it from the second, which is the gap the power gate tolerance is built from.", "Two densities that cannot be compared, because one is formed from a pressure over a height and the other from a rate times a height.", "62.337662337662 lb per ft3 from the first alone. The horsepower packaging carries a volumetric conversion rather than a density.", "62.337662337662 lb per ft3 from both, a difference of 0 lb per ft3."]'::jsonb, 3, '144 square inches per square foot over the measured 2.310000000 gives one, and 33000 ft lbf per minute per horsepower over the measured 3960.000000 with 1728 over 231 gives the other. The 0.999553114 is a different gap entirely: it is the engine against the published power goldens, whose oracle worked through SI watts at a water density of its own.'),
  ('rotating', 'beginner', 'module', 'm04-power-head-and-pressure', 15, 'What is 1714.285714285714 in this module?', '["The implied water density expressed in pounds per cubic inch rather than per cubic foot.", "The ratio of the motor input in horsepower to the motor input in kilowatts, scaled by the default motor efficiency.", "The quotient of the two measured packagings, which is what ties them together and is measurable directly out of the pair.", "The number of gallons per minute that one horsepower lifts through one foot on a fluid of unit gravity."]'::jsonb, 2, 'Change one packaging without changing the other and it moves. That is what makes it a check rather than a coincidence.'),
  ('rotating', 'beginner', 'module', 'm05-where-the-duty-landed', 1, 'Where does the best efficiency flow come from when the operating region is judged?', '["It is read off the fitted curve at the flow where the quadratic turns over, which is the closest the catalogue points come to naming it.", "It is taken as the largest flow in the point set.", "It is stated to the engine. The module does not derive it and the fit cannot recover it.", "It is solved alongside the duty, since the crossing and the best efficiency flow both come out of the same pair of curves."]'::jsonb, 2, 'The four catalogue readings are heads and the best efficiency flow is a statement about efficiency. It comes off the vendor curve and somebody has to type it in.'),
  ('rotating', 'beginner', 'module', 'm05-where-the-duty-landed', 2, 'Ask for the operating region with no best efficiency flow, and ask again at a negative one. What comes back?', '["The same refusal both times: { error: \"a BEP flow is needed to judge the operating region\" }.", "A refusal for the missing figure and a judged return for the negative one, whose sign is dropped before the comparison.", "A judged return both times, built on the largest catalogue flow, with a note saying the figure was assumed.", "A refusal for the negative figure and a judged return for the missing one, which falls back to the module default."]'::jsonb, 0, 'There is no default here. A guessed best efficiency flow would produce a confident verdict about a pump nobody described.'),
  ('rotating', 'beginner', 'module', 'm05-where-the-duty-landed', 3, 'The OKONO region return carries four fields. What kinds of thing are they?', '["Four measurements taken at the duty flow, differing only in the units each one is expressed in.", "Two inputs echoed back and two results.", "A measurement, its uncertainty and a label.", "A measurement, a label, the machine-readable form of that label, and prose."]'::jsonb, 3, 'The percentage is a measurement, the region is a label, the preferred flag is the machine-readable form of that label, and the note is prose.'),
  ('rotating', 'beginner', 'module', 'm05-where-the-duty-landed', 4, 'Why does the return carry both a measurement and a label rather than either one?', '["A measurement alone cannot be shown on screen, and a label alone cannot be tested by the function further down the chain.", "A measurement alone leaves every reader to apply their own bands, and a label alone throws away how close the duty is to an edge.", "A measurement alone would have to be recomputed by every caller, and a label alone would have to be translated before it could be printed.", "A measurement alone is held for literature, and a label alone carries no note to explain what it costs."]'::jsonb, 1, 'Two engineers reading the same duty would otherwise read it differently, and a selection sitting at the edge of its band would look the same as one sitting in the middle.'),
  ('rotating', 'beginner', 'module', 'm05-where-the-duty-landed', 5, 'A caller tests the label, a second caller tests the flag and a third tests for the presence of a note. What do the three get?', '["Three readings that agree in the middle of a band and part company at its edges, which is why the boundary walk exists.", "Three readings that agree except where the note is absent, since a missing note is not the same claim as a cleared flag.", "The same verdict, because the return is built so that no two of them can disagree on any row.", "Three readings that cannot be compared at all."]'::jsonb, 2, 'The flag is true on exactly the rows carrying the label it stands for, and a note is present on exactly the rows where the flag is cleared.'),
  ('rotating', 'beginner', 'module', 'm05-where-the-duty-landed', 6, 'Why is a band table asked on both sides of every boundary rather than in the middle of each band?', '["A comparison written with the wrong kind of inequality misclassifies exactly one value, the boundary value itself, and behaves perfectly at every other flow.", "A band table asked in the middle of each band cannot show that the bands are adjacent, which is the property the boundaries are there to establish.", "The middle of a band is where the classifier is slowest, so a table asked there measures the cost of the call rather than its correctness.", "A duty almost never lands in the middle of a band, so a table asked there is testing a case the module will not meet in service."]'::jsonb, 0, 'That is a defect which hides everywhere except at the edge. The middle is where every implementation agrees.'),
  ('rotating', 'beginner', 'module', 'm05-where-the-duty-landed', 7, 'The boundary walk assigns fifteen flows to fifteen labels and every pair behaves consistently. What has it NOT established?', '["Whether the classifier is stable when the same flow is asked twice, which needs a repeated call rather than a walk.", "Whether the boundaries are in the right places at all, which is the question held for literature.", "Whether the duty those flows were taken from came off a converged solve, which the region call cannot see.", "Whether the module would classify a flow above the largest one on the table, which sits outside the walk."]'::jsonb, 1, 'A correct implementation of a convention is still an implementation of a convention. The repository holds no publication for the boundaries.'),
  ('rotating', 'beginner', 'module', 'm05-where-the-duty-landed', 8, 'The engine note for a duty well below best efficiency flow names a mechanism. What is it?', '["Cavitation at the eye, with the driver overloading.", "A steep climb in the required NPSH.", "Throttling across a control valve, the head lost as heat.", "Suction and discharge recirculation, with bearing and seal life shortening."]'::jsonb, 3, 'Too little flow through an impeller designed for more leaves the passages partly stalled and fluid turns back on itself at the eye and at the periphery.'),
  ('rotating', 'beginner', 'module', 'm05-where-the-duty-landed', 9, 'Why do bearings and seals come into a note about low flow at all?', '["The shaft turns more slowly at low flow, so the bearings spend longer below the speed at which their film forms.", "A throttled discharge raises the pressure the seal holds.", "Recirculation is unsteady, so it loads the shaft in a direction that changes.", "The fluid warms as it recirculates, and the bearings and the seal are the two parts whose life is set by temperature."]'::jsonb, 2, 'That sentence is also the one place in the whole package that says anything at all about seals and bearings, and it says it in prose.'),
  ('rotating', 'beginner', 'module', 'm05-where-the-duty-landed', 10, 'Only one of these four returned notes prescribes a remedy rather than describing a consequence. What does it offer?', '["It prescribes, offering a smaller pump, a trim or a variable speed drive as three ways of making the machine smaller.", "It quotes a figure back, naming the flow at which the duty would return to the band it fell out of.", "It refuses, returning an error string in place of the label the other bands carry.", "It names two failure modes rather than one, arriving from opposite ends of the machine."]'::jsonb, 0, 'A duty that far down the curve usually means a control valve is absorbing the difference between what the pump makes and what the station needs, and that difference is paid for in electricity.'),
  ('rotating', 'beginner', 'module', 'm05-where-the-duty-landed', 11, 'The note for a duty far above best efficiency flow warns about two things. Which two, and from where on the machine?', '["Recirculation at the impeller eye, from the suction side, and shortened seal life, from the discharge end of the machine.", "Running out of NPSH and cavitating, from the suction side, and the driver overloading, from the drive end.", "A steep climb in the required NPSH, from the suction side, and a fall in the delivered head, from the discharge end.", "Wasted power across the control valve, from the discharge side, and damage to the machine, from the impeller."]'::jsonb, 1, 'Two failures in one sentence, arriving from opposite ends. A duty that far to the right threatens both at once.'),
  ('rotating', 'beginner', 'module', 'm05-where-the-duty-landed', 12, 'One of the four notes has three clauses and the middle one is a confession. What does it confess?', '["That the band it fires in has no publication behind it anywhere in this repository.", "That the duty may have come off a cleared flag.", "That the required NPSH was read at the wrong flow.", "That this module carries NPSHr as a single number rather than as a curve."]'::jsonb, 3, 'The engine''s own words are that the module carries NPSHr as a single number rather than a curve, so the vendor curve has to be read at THIS flow before the suction margin means anything.'),
  ('rotating', 'beginner', 'module', 'm05-where-the-duty-landed', 13, 'What form does the required NPSH of a real pump take, and what form does this module carry it in?', '["A single figure quoted at best efficiency flow, carried here as a curve the module fits from the catalogue points.", "A curve against speed rather than against flow, carried here as a scalar taken at the rated speed.", "A curve against flow that rises steeply at the right-hand end, carried here as a scalar the caller types in.", "A band with a low and a high value, carried here as the midpoint of the two."]'::jsonb, 2, 'There is no required-NPSH-against-flow curve anywhere in these two engine modules, which is one of the four absences the course names.'),
  ('rotating', 'beginner', 'module', 'm05-where-the-duty-landed', 14, 'A required NPSH is read off the vendor curve at best efficiency flow and the duty then solves out well above it. What does the suction check return?', '["A margin, a verdict and a severity, all of them computed correctly from a number that does not apply at the flow in question.", "A refusal, because the module detects that the required figure was quoted at a different flow from the duty.", "A margin carrying a warning, since the check compares the duty flow against the flow the required figure was quoted at.", "Nothing at all, because the check is suppressed whenever the duty lands outside the preferred band."]'::jsonb, 0, 'The consequence is exact. The check will be run against a required NPSH that is too low.'),
  ('rotating', 'beginner', 'module', 'm05-where-the-duty-landed', 15, 'The engine met a hazard it could not assess properly. What did it do about it?', '["It invented a required-NPSH curve from the duty and the stated scalar, and said so in the note.", "It ran the calculation it was asked for and marked the assumption that calculation rests on.", "It suppressed the suction check for that duty and returned the note in place of a margin.", "It refused the whole region call, on the ground that a verdict it cannot stand behind is worse than none."]'::jsonb, 1, 'A warning that names the specific limitation of the code producing it and states the action that closes the gap is something a reader can act on today.'),
  ('rotating', 'beginner', 'module', 'm06-the-associate-reading', 1, 'Put the OKONO chain in the order the engine runs it.', '["Build the system curve, solve the crossing, fit the catalogue points to the solved flow, then ask the power and the pressure.", "Fit the catalogue points, build the system curve, solve the crossing, then ask the power, the pressure and the region there.", "Fit the points, ask the power and the region on the fitted curve, then solve the crossing.", "Solve the crossing from the static head, then fit the points to check it."]'::jsonb, 1, 'Each step consumes what the step before it produced. Nothing downstream of the crossing can be asked until the crossing itself exists.'),
  ('rotating', 'beginner', 'module', 'm06-the-associate-reading', 2, 'Which step in that chain consumes the shutoff head, and what does it do with it?', '["The power call, which uses it to bound the head before the specific gravity is applied.", "The region judgement, which expresses the duty head against it as a fraction.", "The system curve, which subtracts it from the static head to form the coefficient.", "The duty solve, which compares it against the system head at zero flow."]'::jsonb, 3, 'If the station demands more head at zero flow than the pump makes at shutoff, the gap never starts positive and there is nothing to find.'),
  ('rotating', 'beginner', 'module', 'm06-the-associate-reading', 3, 'Three ideas run through this tier. Which set is it?', '["A machine has no operating point until it is connected; a return is more than an answer; a flag is worth what its false case is worth.", "A curve is a measurement; a fit is an approximation; a residual is the difference between the two.", "Head belongs to the machine; pressure belongs to the fluid; power belongs to the driver.", "Every constant is measured; every band is held; every refusal is returned."]'::jsonb, 0, 'Everything after the duty in the chain is a consequence of where the duty landed, so everything after it moves when the station moves.'),
  ('rotating', 'beginner', 'module', 'm06-the-associate-reading', 4, 'Two flags in this tier judge a calculation rather than label a result. Name them and the input that clears each.', '["Converged, made false by a search limit below the crossing, and droops, made false by a negative head among the catalogue points.", "Preferred, made false by a duty outside its band, and converged, made false by a fixed halving count with no stopping test.", "Converged, made false by a curve returning a non-finite head over part of its range, and droops, made false by a point set that rises with flow.", "Droops, made false by three identical heads, and preferred, made false by a best efficiency flow the caller did not supply."]'::jsonb, 2, 'A judging flag with no reachable false case is decoration. The tier ran the input that clears each of these two rather than describing it. The preferred flag is a label rather than a judgement, so it is not one of the two.'),
  ('rotating', 'beginner', 'module', 'm06-the-associate-reading', 5, 'What did this tier deliberately not do?', '["It did not fit a curve to fewer than four catalogue points, did not solve a crossing outside the published range, and did not state a motor efficiency.", "It did not go near the suction side, did not change the machine by speed or by trim, did not put a second one beside it, and did not touch a compressor.", "It did not measure any packaging, did not read any golden case, and did not quote any refusal message in the engine''s own words.", "It did not convert a head into a pressure, did not judge where a duty landed, and did not report on the conditioning of a fit."]'::jsonb, 1, 'The suction side is where selections actually fail, and it is the opening of the next tier.'),
  ('rotating', 'beginner', 'module', 'm06-the-associate-reading', 6, 'The Associate capstone grades six answers. Which six?', '["The fitted shutoff head, the condition number, the R squared, the duty flow, the duty head and the brake power.", "The duty flow, the duty head, the percentage of best efficiency flow, the region, the brake power and the discharge pressure.", "The system coefficient, the duty flow, the duty head, the hydraulic power, the pump loss and the motor loss.", "The duty flow, the duty head, the hydraulic power, the brake power, the motor input in kilowatts and the discharge pressure."]'::jsonb, 3, 'The first two are one answer solved once. The last four are all asked at that answer.'),
  ('rotating', 'beginner', 'module', 'm06-the-associate-reading', 7, 'What is the shape of the dependency between those six?', '["Get the duty wrong and all six are wrong, and the four downstream ones will be wrong in a way that looks entirely plausible.", "The six are independent, since each one is a separate export called with its own inputs from the prompt.", "The four downstream answers constrain the duty, so an error in the duty shows up as an inconsistency between the four of them.", "Only the pressure depends on the duty. The three powers are properties of the machine and the fluid alone."]'::jsonb, 0, 'Each of the four is a correct calculation on an incorrect flow, which is why none of them can be checked independently of the duty.'),
  ('rotating', 'beginner', 'module', 'm06-the-associate-reading', 8, 'What should be read off the fit before the fitted curve is used at all?', '["The condition number, because a figure outside the range this course reports means the coefficients cannot be trusted.", "The shutoff head, because it has to be compared against the catalogue reading before the fit is accepted.", "The droop flag, because a cleared one means the crossing about to be solved for is not a duty point.", "The scale, because the curve is written in the normalised variable."]'::jsonb, 2, 'There is no sense computing anything past a cleared droop flag. An R squared of null is a statement about the points rather than about the fit.'),
  ('rotating', 'beginner', 'module', 'm06-the-associate-reading', 9, 'What should be read before the solved flow is read?', '["The bracket, because a width above the resolution of the flow means the search was stopped early.", "The convergence flag, because a flow off an unconverged bisection is a number rather than an answer.", "The halving count, because a count at the cap means the search ran out of budget before it settled.", "The warning string, because it is the only field that names which of the two halves of the flag failed."]'::jsonb, 1, 'The tier has already shown a case where the flow prints normally and is wrong by more than three hundred gallons per minute.'),
  ('rotating', 'beginner', 'module', 'm06-the-associate-reading', 10, 'In what order do the two efficiencies go, and why does the order matter?', '["Motor efficiency turns hydraulic power into motor input, then pump efficiency reduces it to the brake power at the shaft.", "Either order reaches the same three figures, since the two efficiencies multiply and multiplication commutes.", "Pump efficiency turns brake power into motor input, then motor efficiency turns motor input into the supply figure.", "Pump efficiency turns hydraulic power into brake power, then motor efficiency turns brake power into motor input."]'::jsonb, 3, 'Keeping them in that order keeps the shaft figure separate from the supply figure, and the shaft figure is the one the coupling has to survive.'),
  ('rotating', 'beginner', 'module', 'm06-the-associate-reading', 11, 'Which figure does the capstone''s kilowatt answer come from?', '["The brake power, converted, since the kilowatt is the shaft figure expressed in electrical units.", "The hydraulic power, converted, since the kilowatt answers what the duty is worth rather than what the supply delivers.", "The motor input, converted.", "The motor input, converted at the default motor efficiency rather than at the one the prompt states."]'::jsonb, 2, 'Converting the brake power instead leaves out the whole of the motor''s own loss.'),
  ('rotating', 'beginner', 'module', 'm06-the-associate-reading', 12, 'Why is working the six graded answers in the order they are listed a mistake?', '["The list is an order of presentation, and the order of computation is fit, system, duty, then everything else.", "The list is ordered by how heavily each answer is weighted, which is unrelated to what each one depends on.", "The list interleaves the two efficiencies, so working down it applies the motor efficiency before the pump efficiency.", "The list omits the fit and the system curve, so working down it produces six answers and no evidence for any of them."]'::jsonb, 0, 'The four downstream answers cannot be checked independently of the duty they were asked at.'),
  ('rotating', 'beginner', 'module', 'm06-the-associate-reading', 13, 'A duty point that works on paper fails in three ways, and the next tier is all three. Which three?', '["On conditioning, on convergence and on the shape of the curve, which are the three reports the fit and the solve carry.", "On suction, on change and on the fluid.", "On the driver, on the seal and on the bearings, which are the three parts a duty in the wrong band shortens the life of.", "On the stage count, on the interstage cooling and on the fuel, which are the three the compressor half of the course adds."]'::jsonb, 1, 'Available NPSH built from the real suction survey, a speed change against an impeller trim, and a catalogue curve that is a water curve.'),
  ('rotating', 'beginner', 'module', 'm06-the-associate-reading', 14, 'What does holding an item for literature mean for the way this course uses it?', '["It is printed with a warning and may still decide a graded answer.", "It is excluded from the engine entirely.", "It is graded only in the tier that teaches it.", "It is used, it is printed and it never decides a graded answer anywhere in the course."]'::jsonb, 3, 'Eight things are held on that footing, each because this repository holds no publication behind it.'),
  ('rotating', 'beginner', 'module', 'm06-the-associate-reading', 15, 'Which of these is held for literature in this course?', '["The affinity speed law, which the engine applies exactly and which the Professional tier of this course grades.", "The conversion between feet of head and psi, whose packaging the engine defines and this very tier measures out of it.", "The impeller trim shortfall model, whose engine comment calls it a published shortfall and names no publication.", "The convergence flag on the duty solve, which is reported rather than derived from any published criterion."]'::jsonb, 2, 'The eight held items are the viscosity correction, the trim shortfall, the operating-region bands, the NPSH margin rule, the machine-screening thresholds, the default discharge limit, what the implied water density is away from real water, and every published golden case.'),
  ('rotating', 'beginner', 'final', null, 1, 'A single units file is read by both pumps.js and compression.js. What does that arrangement buy?', '["One definition of a horsepower serving the liquid machine and the gas machine, so the kilowatt a pump return prints and the Btu per horsepower-hour a compression return works in rest on the same foot, pound and standard gravity.", "A single point at which a caller can override the packagings for a project working in other units.", "A guarantee that the two modules were written at the same time and carry the same vintage of every constant.", "A place for the two modules to keep the compressibility window they both have to work inside."]'::jsonb, 0, 'Two modules that each need a horsepower could have written one each. They read one file instead. pumps.js takes the kilowatt conversion from it and compression.js takes the two it needs.'),
  ('rotating', 'beginner', 'final', null, 2, 'A junior engineer reports that a pump sizing call raised no exception, so the inputs must have been accepted. What is the flaw?', '["Exceptions are raised only for inputs that are absent, so an input that is present and out of its domain passes through the guard silently.", "The studio catches the exception before the caller sees it, so the absence of one at the call site proves nothing.", "Neither module throws, so a refused call comes back as an ordinary object with an error string in it and nothing is raised at all.", "The refusal is raised on the next call rather than this one, because the guards run one step behind the chain."]'::jsonb, 2, 'A caller checks a property on the result rather than wrapping the call in a try block.'),
  ('rotating', 'beginner', 'final', null, 3, 'Why is NaN a better refusal than a plausible number for an export with nowhere to put an error string?', '["NaN is the only value the print formatting refuses to render, so it cannot reach a report at all.", "A plausible number would be caught by the next guard in the chain, which costs a call that NaN saves.", "NaN is cheaper to produce, because the export can return before doing any of the arithmetic.", "Nothing downstream could ever detect a plausible number, and NaN fails every comparison including one with itself."]'::jsonb, 3, 'It poisons any arithmetic it touches, so a caller who ignores it gets a result that is visibly broken rather than quietly wrong.'),
  ('rotating', 'beginner', 'final', null, 4, 'A station study claims the selected compressor is safe across its whole turndown. Which part of that claim do these engines have nothing to say about?', '["The discharge temperature at low rate, which the module computes only at the rated point.", "All of it below the point where the machine stops delivering, because there is no surge line and no surge margin anywhere in the package.", "The power at low rate, which the module reports only as a total across the train.", "The stage count at low rate, which the module fixes at the design case and does not revisit."]'::jsonb, 1, 'With the surge line go the recycle valve and the anti-surge calculation. A result that says nothing about a failure mode is not a result that clears it.'),
  ('rotating', 'beginner', 'final', null, 5, 'A pump report is asked to include the pressure drop through the discharge piping. Where does that number come from?', '["The system curve, which already carries it as the friction head the caller supplied.", "The duty solve, which separates the static and friction parts of the duty head.", "engines/facilities/lineHydraulics.js, which is a different engine module and a different course.", "The discharge pressure conversion, which turns the friction head into psi at the service gravity."]'::jsonb, 2, 'These two modules size machines. The system curve takes a friction head as an input rather than working it out.'),
  ('rotating', 'beginner', 'final', null, 6, 'Two of the pump module''s refusals concern the static head and the friction head of a system curve. What is the asymmetry between them?', '["A negative static head is accepted and a negative friction head is not.", "A missing static head is accepted and a missing friction head is not, because the coefficient can be formed without the lift.", "Negative friction is accepted and negative static is not.", "Both are refused when negative."]'::jsonb, 0, 'The message says a static head may be negative but cannot be missing. A pump discharging into a vessel below it is an ordinary station.'),
  ('rotating', 'beginner', 'final', null, 7, 'A catalogue of four readings is handed to the fit. How many of them does the fitted curve pass through?', '["All four, which is what distinguishes a least-squares fit from an interpolation.", "Three, the fourth being the shutoff reading, which is used to fix c0 rather than fitted.", "Two, the fit being anchored at the ends of the published range and free between them.", "None, because a quadratic has three coefficients and four points leave no curve that hits all of them."]'::jsonb, 3, 'The four residuals are 0.203016, -0.593431, 0.551043 and -0.160628 ft, and the signs alternate down the column.'),
  ('rotating', 'beginner', 'final', null, 8, 'What is the scale in the OKONO fit taken from, and what is it for?', '["The largest head in the point set, 540.000000 ft, used to normalise the head so the residuals are dimensionless.", "The largest flow in the point set, 1900.000000 gpm, used to normalise the flow before the quadratic is solved.", "The flow at which the friction head is stated, 1100.000000 gpm, so that both curves share one reference.", "The shutoff head of 540.203016 ft, used to express the fall in head as a fraction of what the machine makes at no flow."]'::jsonb, 1, 'The quadratic is written in q over the scale, which keeps the three coefficients within a few orders of magnitude of each other.'),
  ('rotating', 'beginner', 'final', null, 9, 'The four OKONO residuals are 0.203016, -0.593431, 0.551043 and -0.160628 ft. What is notable about that column?', '["They fall in magnitude as the flow rises, which is the fit tracking the steepening part of the curve more closely than the flat part.", "They are largest at the two ends of the range, where the quadratic has least freedom to bend.", "The signs alternate down it, which is a fit behaving.", "They are all positive, since a least-squares fit sits above every reading it was given."]'::jsonb, 2, 'Alternating signs are the pattern a least-squares curve leaves when it threads scattered readings rather than chasing any one of them.'),
  ('rotating', 'beginner', 'final', null, 10, 'Two fits come back, one with an R squared of 0.999985896 and one with an R squared of 1.000000000. Which is the better pump curve?', '["That cannot be decided from those two figures, because R squared grades the fit against its points and says nothing about the shape.", "The second, whose perfect score means the readings and the curve agree exactly at every point supplied.", "The first, because a perfect R squared means the fit had no freedom left and the point count must have been at the minimum.", "The second, provided its condition number also sits inside the range this course reports."]'::jsonb, 0, 'The perfect score belongs to a rising point set, which the same return disowns with a droops flag of false and a warning in prose.'),
  ('rotating', 'beginner', 'final', null, 11, 'The engine could have answered 1 or 0 for R squared on a flat point set. What would either choice have handed the caller?', '["A score that could be compared against the OKONO fit, which is the comparison the null return makes impossible for a reader to draw.", "A value the conditioning report would then contradict, since the two are formed from the same matrix.", "An answer consistent with the droop flag, which is also false on that point set.", "A number standing where there is no number, which whatever reads the return next would take for an honest measurement."]'::jsonb, 3, 'R squared is the share of the variance the fit explains, and three identical heads have no variance at all.'),
  ('rotating', 'beginner', 'final', null, 12, 'The OKONO condition number of 334.938111 is described as unremarkable. Against what?', '["The sixteen decimal digits that double precision carries, of which a figure of this size costs the coefficients two or three.", "The band the reported figure occupies across all seven of the point sets this course fits without a refusal.", "The 366.680892 of the first published curve golden, which is the only other figure the course reports.", "The conditioning note, which the engine would have filled in had the figure been anywhere near a limit."]'::jsonb, 1, 'Conditioning is hard to read from one figure. Seen against its own spread, a few hundred is ordinary for this solve.'),
  ('rotating', 'beginner', 'final', null, 13, 'The engine both warns in prose and sets a boolean about a curve that climbs with flow. Which of the two can the duty solve act on?', '["The boolean, which is the half the next function can test.", "The prose, because it names the fault and the remedy, which is what the solve reports back to the caller.", "Both equally, since the solve parses the warning string when the boolean is absent from an older return.", "Neither. The solve refits the points itself rather than reading either field."]'::jsonb, 0, 'A warning string can be shown on a screen and can carry advice. Only the flag can be read by the code that acts on it.'),
  ('rotating', 'beginner', 'final', null, 14, 'On the OKONO pair of curves the difference column reads 18.187407 ft at one flow and -157.467056 ft at the next. What has that pair of rows fixed?', '["The residual the solve will finish on, which is bounded by the smaller of the two figures.", "The two flows the answer must lie between, since the column changes sign there.", "The bracket the search starts from, which the engine takes as the two heads rather than the two flows.", "The static head of the station, which is what the two figures differ by."]'::jsonb, 1, 'A sign change across one interval is a bracket. The bisection needs exactly that and nothing more before it can start.'),
  ('rotating', 'beginner', 'final', null, 15, 'The OKONO duty solve reports 55 halvings against a cap of 200. What does the gap between those two figures mean?', '["The search used a quarter of its budget and would have improved the answer had it been allowed the rest.", "The cap was never reached, so the convergence flag was set on the halving count alone.", "The search stopped because the midpoint stopped moving rather than because it ran out of budget.", "The remaining halvings were spent confirming the residual, which is why the bracket is so much smaller than the tolerance."]'::jsonb, 2, 'The cap of 200 is a guard rather than a plan. The loop breaks exactly where a blind one was already standing still.'),
  ('rotating', 'beginner', 'final', null, 16, 'In the negative control the search finishes on a bracket of 1.1368683772161603e-13 gpm. What does that width prove?', '["That the curve returned a non-finite head at the flow the search settled on.", "Nothing about correctness. The search collapsed exactly as it always does, and it collapsed onto the wrong flow.", "That the search ran one halving longer than the healthy solve and therefore overshot.", "That the two curves agree at that flow to within the resolution of the numbers themselves."]'::jsonb, 1, 'A flag made only of that bracket would have called the solve converged and would have been telling the truth about the bracket.'),
  ('rotating', 'beginner', 'final', null, 17, 'The negative control returns a flow, a head and a cleared flag rather than a refusal. What does the caller gain?', '["The ability to see how far off the search went, which a refusal carrying no numbers would not give.", "A result that can be fed into the power call, since the flow is still inside the searched range.", "A guarantee that the fields will be filled in, which a refusal object does not offer for any export.", "An answer that can be compared against the blind loop, which is the only other way to reach the same flow."]'::jsonb, 0, 'The return is complete and every field in it prints normally. The one field that says the number is wrong is the one a hurried caller skips.'),
  ('rotating', 'beginner', 'final', null, 18, 'Which of the duty solver''s refusals is a statement about the search rather than about the hardware?', '["The one saying the curve does not fall with flow, since a rising point set is a data fault rather than a machine fault.", "The one saying this pump cannot start this system, since the caller chose the static head.", "The one saying the curves do not cross below the stated limit.", "The one saying both a pump curve and a system curve are needed, since a missing object is a calling error."]'::jsonb, 2, 'Nothing is wrong with the pump and nothing is wrong with the station. The message offers both readings: raise the limit, or check the system curve.'),
  ('rotating', 'beginner', 'final', null, 19, 'A selection is refused because the pump cannot start the system. What does the evidence in that refusal let an engineer work out?', '["Which of the four catalogue readings was responsible, since the refusal names the point it judged on.", "What flow the station would run at with a larger static head, since the refusal carries the crossing it found first.", "Whether the fit or the system curve was at fault, since the refusal names the object it was reading when it stopped.", "How much bigger the machine has to be, since the shutoff head and the static head are both handed back."]'::jsonb, 3, '540.203016 ft of shutoff against a static head of 700.000000 ft, a gap of 159.796984 ft. That is the difference between being told no and being told how much.'),
  ('rotating', 'beginner', 'final', null, 20, 'The same OKONO machine is put into three different stations. What does that do to the duty flow?', '["It gives one flow with three different heads, since the machine fixes the flow and the station fixes the head.", "It gives three different flows, 1234.452969 gpm, 804.694816 gpm and 1103.518695 gpm, off one set of catalogue readings.", "It gives three flows that differ only in the static part of the head, the friction part being a property of the pump.", "It gives three flows whose average is the rated flow the catalogue would print."]'::jsonb, 1, 'A duty point is a property of a pump and a station together. The rating belongs to the curve and the duty belongs to the installation.'),
  ('rotating', 'beginner', 'final', null, 21, 'Why does stating a system as a friction head at a flow tell an engineer more than stating it as a coefficient?', '["A measured pair is what a station can actually supply, and the coefficient is then the engine''s own arithmetic.", "A coefficient cannot be read back off the return, so a station stated that way loses the evidence for its own curve.", "A coefficient carries the static head inside it, so the two parts of the head cannot be separated at the duty.", "A coefficient is expressed in the normalised variable of the fit, so it has to be rescaled before either curve can be solved."]'::jsonb, 0, 'Nobody walks a station with an instrument reading ft per gpm squared. They read a head and the flow it was read at.'),
  ('rotating', 'beginner', 'final', null, 22, 'Three powers come out of the OKONO duty. Which one is the driver specified against?', '["The hydraulic power of 135.450994 hp, which is the work actually done on the fluid.", "The motor input of 198.958569 hp, which is what the electrical supply has to deliver.", "The motor input of 148.363379 kW, which is the same figure in the units the load list uses.", "The brake power of 183.041884 hp."]'::jsonb, 3, 'Hydraulic power tells you what the duty is worth, and motor input is what the electrical load list and the running cost are built on.'),
  ('rotating', 'beginner', 'final', null, 23, 'The pump loses 47.590890 hp and the motor a further 15.916686 hp. Where did those two figures come from?', '["From the two stated efficiencies applied to the hydraulic power, each loss being the efficiency times the duty.", "From the three powers, by subtraction, each loss being the step between one figure and the next.", "From the engine, which reports each loss as a field of its own beside the three powers.", "From the default motor efficiency, which fixes the motor loss, with the pump loss taking the remainder."]'::jsonb, 1, 'Two efficiencies applied in series, each taking its share. The pump efficiency acts on the hydraulic power and the motor efficiency acts on the shaft power.'),
  ('rotating', 'beginner', 'final', null, 24, 'What changes inside the machine between the lightest and the heaviest fluid in the five-row pressure table?', '["It works harder on the heavier fluid, which is why the head column is held while the pressure column moves.", "It spins at a speed set by the fluid, which is what the specific gravity enters the conversion as.", "Nothing. It raises every one of those fluids by the same height, and what each fluid weighs turns that height into a pressure.", "It delivers the same pressure and a different head, the table being printed with the two columns the other way about."]'::jsonb, 2, 'It spins at the same speed and throws the fluid out at the same velocity on every row. Only the weight of what it is throwing has moved.'),
  ('rotating', 'beginner', 'final', null, 25, 'A pump is quoted at 188.100891 psi in produced-water service. What travels unchanged if the same machine is moved to a light condensate?', '["The discharge pressure, which is a property of the machine at its duty.", "The hydraulic power, since the duty flow and the duty head are both unchanged.", "The brake power, since the pump efficiency belongs to the machine rather than to the fluid.", "The head."]'::jsonb, 3, 'A curve in feet is a property of the machine alone, which is why one catalogue serves every service the machine will ever see.'),
  ('rotating', 'beginner', 'final', null, 26, 'The engine gate against the published power goldens is written with a tolerance rather than demanding equality. What has to set the size of that tolerance?', '["The precision this course prints pump work to, six decimals, since a gate cannot see past the figures it is shown.", "The size of the disagreement the two routes really have, which across the published power and NPSH cases is 0.0005254484459904507 at its largest.", "Nothing sets it. A golden written by an oracle carrying fifty digits is exact, so the gate demands equality and the tolerance exists only to absorb the print formatting.", "Whatever is loose enough that no published case has ever failed it, since a gate that fails on arithmetic rather than on error is worse than no gate at all."]'::jsonb, 1, 'The engine''s 123.834499 hp meets a golden 123.889863 hp because the golden was written through SI watts at a water density its own oracle states. A tolerance loose enough to swallow a mis-transcribed constant catches nothing, so the useful question about any tolerance is what error it is still small enough to see.'),
  ('rotating', 'beginner', 'final', null, 27, 'Two of the four figures measured out of pumps.js are field packagings and two are not. Which two are the packagings?', '["0.745699871582 and 0.940000000000, the kilowatt conversion and the default the engine falls back on when no motor efficiency is stated.", "2.310000000 and 0.745699871582, the two that turn one unit of the chain into another.", "2.310000000 and 3960.000000.", "3960.000000 and 62.337662337662, the horsepower packaging and the density it carries."]'::jsonb, 2, 'The kilowatts per horsepower is a unit conversion out of the shared units file, and 0.940000000000 is a default rather than a constant at all.'),
  ('rotating', 'beginner', 'final', null, 28, 'The motor efficiency argument is left off the power call and three complete powers come back. What has the engine done?', '["The engine has used 0.940000000000, and nothing on screen says the figure was assumed.", "The engine has used the pump efficiency in its place.", "The engine has returned the brake power in the motor input field, so the motor loss is absent.", "The engine has refused the motor input field."]'::jsonb, 0, 'The power lesson stated 0.920000 and the engine used it. Leave the argument off and the answer looks exactly as complete as before.'),
  ('rotating', 'beginner', 'final', null, 29, 'Two packagings written into different functions for different purposes are each unpicked for the density they carry. What is the finding?', '["They differ by a quotient of 0.999553114, which is the disagreement the power gate is written with a tolerance to cover.", "Only one of them carries a density.", "They differ by the ratio 1714.285714285714.", "They agree exactly, both implying 62.337662337662 lb per ft3."]'::jsonb, 3, 'They agree exactly. The 0.999553114 belongs to a different comparison, the engine against the published power goldens, where 123.834499 hp meets a golden 123.889863 hp. The alternative would have been two slightly different waters living in one engine.'),
  ('rotating', 'beginner', 'final', null, 30, 'What is held for literature about the water density this tier measures?', '["The density itself, because it is written inline rather than exported and cannot be quoted.", "What that implied density is away from real water, because the handbook figure it approximates is not in this repository.", "The difference between the two packagings, because no publication states how close they should be.", "The quotient that ties the two packagings together, because it is derived rather than measured."]'::jsonb, 1, 'The packagings are the engine''s own definitions and they are measurable, which is why the figures can be stated at all.'),
  ('rotating', 'beginner', 'final', null, 31, 'No best efficiency flow is supplied. Why is a refusal a better return here than a sensible assumption?', '["A best efficiency flow can be recovered from the catalogue points, so the assumption would be redundant.", "The module has no default to fall back on because the figure differs between the two engine modules.", "A guessed best efficiency flow would produce a confident verdict about a pump nobody described.", "The refusal is the only way to signal that the duty solve itself has not yet been run."]'::jsonb, 2, 'The module has no default for this input, and the refusal is the same whether the figure is missing or negative.'),
  ('rotating', 'beginner', 'final', null, 32, 'Why can the least-squares fit not recover the best efficiency flow from the catalogue it was handed?', '["The readings are heads and the best efficiency flow is a statement about efficiency.", "The readings are too few, and a fifth point at the design flow would be enough to recover it.", "The readings are normalised by the scale.", "The readings are smoothed by least squares."]'::jsonb, 0, 'A head reading and an efficiency reading are different measurements. The catalogue supplied only the first kind.'),
  ('rotating', 'beginner', 'final', null, 33, 'Four test flows, one comfortably inside each band, and the classifier passes. What has that test not exercised?', '["A band whose two ends have been written the wrong way round, which misclassifies everything inside it.", "The boundary values themselves, which are the only flows a wrongly written inequality misclassifies.", "A classifier that ignores the stated best efficiency flow, which misclassifies every flow it is given.", "A classifier that returns the label without the note, which misclassifies nothing and reports less."]'::jsonb, 1, 'An implementation with the wrong inequality answers correctly at every flow except one, and that one is never in the middle of a band.'),
  ('rotating', 'beginner', 'final', null, 34, 'The boundary walk in this tier pairs each boundary with a point a tenth of a percent outside it. What does the completed table prove?', '["That the boundaries sit exactly where pump practice puts them, which is what makes the labels usable in a real selection.", "That the duty of the OKONO station is comfortably clear of every boundary in the table.", "That the classifier is the only part of the module whose behaviour is fully covered by the course.", "That the classifier assigns those flows to those labels and that its boundaries behave consistently."]'::jsonb, 3, 'It says nothing at all about whether the boundaries are in the right places, which is the question held for literature.'),
  ('rotating', 'beginner', 'final', null, 35, 'One returned note tells the reader that the module producing it cannot assess the hazard it has just described. What is the limitation?', '["The module carries the best efficiency flow as an input rather than deriving it from the catalogue.", "The module carries the operating bands as fixed percentages rather than as vendor-supplied limits.", "The module carries the required NPSH as a single number rather than as a curve against flow.", "The module carries no record of whether the duty it was handed came off a converged solve."]'::jsonb, 2, 'The note is about the module rather than about the pump. The pump is fine, and the figure supplied about it has stopped applying.'),
  ('rotating', 'beginner', 'final', null, 36, 'What does the module do when the required NPSH it was handed no longer applies at the flow the duty solved to?', '["It runs the check anyway and marks the assumption, returning every field it would otherwise return.", "A refusal, because the module compares the flow the figure was quoted at against the duty flow.", "A margin with the severity suppressed, because the module knows the figure is out of date.", "A margin computed on the required NPSH the module interpolates to the duty flow."]'::jsonb, 0, 'It computed what it was asked for and said, in the return itself, what that computation rests on. Nothing was invented and nothing was hidden.'),
  ('rotating', 'beginner', 'final', null, 37, 'The engine''s note about running well below best efficiency flow is the only place in the package where two machine parts are mentioned at all. Which two?', '["Impellers and wear rings, whose clearances the note says open up at low flow.", "Bearings and seals.", "Couplings and shafts, which the note says are loaded in a direction that changes.", "Valves and recycle lines, which the note offers as the remedy for the condition."]'::jsonb, 1, 'Recirculation is unsteady, so it loads the shaft in a direction that changes. That sentence in prose is the whole of what the package knows about them.'),
  ('rotating', 'beginner', 'final', null, 38, 'In what order should the Associate capstone be worked?', '["Duty, then fit, then system curve, then the power and the pressure, since the duty fixes which part of the curve is in use.", "System curve, then duty, then fit, then the power and the pressure, since the station is what the machine is chosen against.", "Fit, then duty, then system curve, then the power and the pressure, since the crossing is solved on the fitted curve alone.", "Fit, then system curve, then duty, then the power and the pressure."]'::jsonb, 3, 'The list of six graded answers is an order of presentation. Working down it produces four correct calculations on an unchecked flow.'),
  ('rotating', 'beginner', 'final', null, 39, 'Which of the capstone answers are correct calculations on whatever duty flow they happen to be handed?', '["Only the discharge pressure, since the three powers are taken from the catalogue rather than from the crossing.", "Only the two powers expressed in horsepower, the kilowatt figure being a conversion of a conversion.", "All four that sit downstream of it.", "None of them, since each is a separate export called with inputs taken straight from the prompt."]'::jsonb, 2, 'That is what makes a wrong duty so hard to spot downstream: none of the four can disagree with it, because each one was computed from it.'),
  ('rotating', 'beginner', 'final', null, 40, 'What is the single habit this tier has been teaching, made concrete by the capstone?', '["Check every flag before using the number beside it.", "Measure every packaging before quoting it, since none of them is exported or named.", "State every efficiency explicitly.", "Solve every crossing before quoting a flow."]'::jsonb, 0, 'The capstone is built so that it pays. A judging flag with no reachable false case is decoration, and this tier ran the false case of both converged and droops.'),
  ('rotating', 'beginner', 'final', null, 41, 'Two answers from the capstone are held up: the duty flow and the discharge pressure. What is each a property of?', '["The duty flow of the pump alone, and the discharge pressure of the pump and the fluid together.", "The duty flow of the pump and the station together, and the discharge pressure of the pump, the station and the fluid together.", "Both of the pump and the station together, the fluid entering only the power chain.", "The duty flow of the station alone, and the discharge pressure of the machine alone."]'::jsonb, 1, 'Neither is a property of the machine by itself, which is the mistake every version of the tier''s warnings comes back to.'),
  ('rotating', 'beginner', 'final', null, 42, 'What does the next tier add that this one deliberately left out?', '["The compressor, its stage count, the cooling between its stages and the fuel the driver on the end of it burns.", "The published golden cases and the tolerance an engine gate against them has to carry.", "The suction survey, a change of speed or diameter, and the fact that a catalogue curve is a water curve.", "The conditioning of the fit and the report the duty solve leaves behind."]'::jsonb, 2, 'Those are the three ways a duty that works on paper fails, and the whole of that tier is built around them.');
